import {categories,projects,packages,currency} from "./assets/catalog.js";
const $=s=>document.querySelector(s),esc=s=>String(s).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c])),icon=name=>`<svg aria-hidden="true"><use href="./assets/icons.svg#${name}"></use></svg>`,dialog=$("#dialog");
let filter="all",packageCategory="photo",lightbox=[],lightIndex=0,opener,openerData,toastTimer,draft="";
function toast(message){clearTimeout(toastTimer);$("#toast").textContent=message;$("#toast").hidden=false;toastTimer=setTimeout(()=>$("#toast").hidden=true,3500);}
function syncUrl(push=true,hash){const url=new URL(location.href);url.searchParams.set("work",filter);url.searchParams.set("package",packageCategory);if(hash)url.hash=hash;history[push?"pushState":"replaceState"](null,"",url);}
function restore(){const p=new URLSearchParams(location.search);filter=["all",...categories.map(c=>c.id)].includes(p.get("work"))?p.get("work"):"all";packageCategory=categories.some(c=>c.id===p.get("package"))?p.get("package"):"photo";}
function renderGallery(){
  const visible=filter==="all"?projects:projects.filter(p=>p.category===filter);
  $("#filters").innerHTML=[{id:"all",name:"All work"},...categories].map(c=>`<button data-filter="${c.id}" aria-pressed="${c.id===filter}">${c.name}</button>`).join("");
  $("#work-count").textContent=`${visible.length} VISUAL STUDIES / SAMPLE MATERIAL`;
  $("#gallery").classList.toggle("filtered",filter!=="all");
  $("#gallery").innerHTML=visible.map(p=>`<button class="project" data-project="${p.id}" aria-label="Open ${esc(p.title)}"><img src="./assets/${p.image}" alt="${esc(p.alt)}" loading="lazy" width="1000" height="750"><i>${icon(p.video?"play":"arrow-up-right")}</i><span class="project-text"><small>${categories.find(c=>c.id===p.category).name.toUpperCase()} / ${p.video?"ORIGINAL ANIMATION":"SAMPLE PHOTO"}</small><strong>${p.title}</strong><span>${p.subtitle}</span></span></button>`).join("");
}
function renderPackages(){
  $("#package-tabs").innerHTML=categories.map(c=>`<button id="package-tab-${c.id}" data-package-tab="${c.id}" role="tab" aria-controls="package-panel" aria-selected="${c.id===packageCategory}" tabindex="${c.id===packageCategory?0:-1}">${c.name}</button>`).join("");
  $("#package-panel").setAttribute("aria-labelledby","package-tab-"+packageCategory);
  $("#package-panel").innerHTML=packages.filter(p=>p.category===packageCategory).map(p=>`<article class="package-row"><div class="package-name"><span>SAMPLE PACKAGE / ${p.category.toUpperCase()}</span><h3>${p.name}</h3></div><ul>${p.features.map(f=>`<li>${icon("check")}${f}</li>`).join("")}</ul><div class="package-price"><strong>${currency(p.price)}</strong><span>/ ${p.unit}${p.minimum?" · min. "+p.minimum+" participants":""}</span></div><button class="button" data-action="inquire" data-package="${p.id}">Choose package ${icon("arrow-up-right")}</button></article>`).join("");
}
function mount(title,body,wide=false){
  $("#dialog video")?.pause();if(!dialog.open){opener=document.activeElement;openerData=opener?.dataset?{...opener.dataset}:{};dialog.showModal();}
  dialog.classList.toggle("wide",wide);$("#dialog-content").innerHTML=`<h2 id="dialog-title">${title}</h2>${body}`;$("#close").focus({preventScroll:true});dialog.scrollTop=0;
}
function close(){
  $("#dialog video")?.pause();dialog.close();$("#dialog-content").replaceChildren();dialog.classList.remove("wide");draft="";lightbox=[];
  const selector=openerData?.project?`[data-project="${openerData.project}"]`:openerData?.action?`[data-action="${openerData.action}"]${openerData.package?`[data-package="${openerData.package}"]`:""}`:null;
  const fallback=selector?document.querySelector(selector):null;(opener?.isConnected?opener:fallback||$("#work")).focus?.({preventScroll:true});
}
function showProject(){
  const p=lightbox[lightIndex];
  mount(esc(p.title),`${p.video?`<video id="film" class="lightbox-video" controls playsinline preload="metadata" poster="./assets/${p.image}"><source src="./assets/${p.video}" type="video/webm">This browser does not support WebM. The poster and description remain available.</video><p class="dialog-note" id="video-status">Original six-second title animation, with no audio. Playback does not start automatically.</p>`:`<img class="lightbox-img" src="./assets/${p.image}" alt="${esc(p.alt)}">`}<p class="dialog-note">${p.description}</p><div class="lightbox-nav"><span>${lightIndex+1} / ${lightbox.length} · ${p.video?"ORIGINAL ANIMATION":"SAMPLE MATERIAL"}${p.source?` · <a href="${p.source}" target="_blank" rel="noopener noreferrer">Photo source</a>`:""}</span><div><button class="icon-button" data-action="previous" aria-label="Previous project" ${lightbox.length===1?"disabled":""}>${icon("arrow-left")}</button><button class="icon-button" data-action="next" aria-label="Next project" ${lightbox.length===1?"disabled":""}>${icon("arrow-right")}</button></div></div>`,true);
  $("#film")?.addEventListener("error",()=>{$("#video-status").textContent="This browser could not play the video. The poster and description remain available; no external player is used."});
}
function openProject(id){const visible=filter==="all"?projects:projects.filter(p=>p.category===filter),p=projects.find(p=>p.id===id);if(!p)return;lightbox=visible.includes(p)?visible:[p];lightIndex=lightbox.indexOf(p);showProject();}
function today(){const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,"0")}-${String(d.getDate()).padStart(2,"0")}`;}
function inquiry(packageId){
  const selected=packages.find(p=>p.id===packageId)||packages.find(p=>p.category===packageCategory);
  draft="";
  mount("Every story starts with hello.",`<p class="dialog-note">This is a local draft composer, not a booking form. No official WhatsApp number is available. No payment, automatic sending, availability check, or reservation takes place.</p><form id="inquiry-form"><div class="form-grid"><label class="wide">Sample package<select name="package">${packages.map(p=>`<option value="${p.id}" ${selected.id===p.id?"selected":""}>${categories.find(c=>c.id===p.category).name} — ${p.name}</option>`).join("")}</select></label><label>Planned date<input name="date" type="date" min="${today()}" required></label><label>Planned city / location<input name="city" maxlength="50" required placeholder="Example: Yogyakarta"></label><label class="wide" id="quantity-label" ${selected.minimum?"":"hidden"}>Participants (minimum 30)<input name="quantity" type="number" step="1" min="${selected.minimum||1}" max="500" value="${selected.minimum||1}"></label><label class="wide">Tell us what you need (optional)<textarea name="note" maxlength="300" placeholder="Concept, group size, or questions…"></textarea></label></div><div class="estimate"><small>SAMPLE BASE ESTIMATE / NOT A FINAL TOTAL</small><strong id="estimate"></strong><p id="package-note"></p><p>Taxes, travel, additional vendors, and other costs are undetermined. Availability has not been checked.</p></div><p class="form-error" id="form-error" role="status"></p><div class="form-actions"><button class="button gold">Prepare message draft ${icon("arrow-right")}</button><button class="button" type="button" data-action="close">Cancel</button></div></form>`);
  const update=()=>{const p=packages.find(p=>p.id===$("#inquiry-form [name=package]").value),input=$("#inquiry-form [name=quantity]");$("#quantity-label").hidden=!p.minimum;input.min=String(p.minimum||1);input.required=Boolean(p.minimum);const quantity=p.minimum?Number(input.value):1;$("#estimate").textContent=Number.isInteger(quantity)&&quantity>=(p.minimum||1)&&quantity<=500?currency(p.price*quantity):"Invalid participant count";$("#package-note").textContent=p.note;};
  $("#inquiry-form [name=package]").addEventListener("change",()=>{const p=packages.find(p=>p.id===$("#inquiry-form [name=package]").value);$("#inquiry-form [name=quantity]").value=String(p.minimum||1);update();});
  $("#inquiry-form [name=quantity]").addEventListener("input",update);update();
  $("#inquiry-form").addEventListener("submit",e=>{
    e.preventDefault();const f=new FormData(e.target),p=packages.find(p=>p.id===f.get("package")),date=f.get("date"),city=f.get("city").trim(),note=f.get("note").trim(),quantity=p.minimum?Number(f.get("quantity")):1;
    if(!/^\d{4}-\d{2}-\d{2}$/.test(date)||!Number.isFinite(Date.parse(date+"T00:00:00Z"))||new Date(date+"T00:00:00Z").toISOString().slice(0,10)!==date||date<today()||!city||city.length>50||note.length>300||!Number.isInteger(quantity)||quantity<(p.minimum||1)||quantity>500){$("#form-error").textContent="Complete a valid date from today onward, a city, and a valid participant count.";return;}
    draft=`LENTERA CONCEPT DRAFT — NOT A BOOKING\n\nHello, I would like to ask about the sample package ${p.name} (${categories.find(c=>c.id===p.category).name}).\nPlanned date: ${date}\nCity / location: ${city}\n${p.minimum?"Participants: "+quantity+"\n":""}Sample base price: ${currency(p.price)} / ${p.unit}\nSample base estimate: ${currency(p.price*quantity)}\nTaxes, travel, additional vendors, and the final total are undetermined. Availability has not been checked.\n${note?"\nNotes: "+note+"\n":""}\nThe official studio number is unverified. This is only a draft; it has not been sent or confirmed.`;
    mount("Your draft is ready. Nothing has been sent.",`<p class="dialog-note">No official studio number is available. This link opens WhatsApp to choose a recipient yourself and passes the draft to WhatsApp. No booking, payment, or automatic sending takes place.</p><textarea id="draft" class="draft" readonly aria-label="Unsent message draft">${esc(draft)}</textarea><div class="form-actions"><a class="button gold" id="whatsapp" href="https://wa.me/?text=${encodeURIComponent(draft)}" target="_blank" rel="noopener noreferrer">Choose a recipient in WhatsApp ${icon("arrow-up-right")}</a><button class="button" data-action="copy">Copy draft ${icon("copy")}</button><button class="button" data-action="download">Download text ${icon("download")}</button></div>`);
  });
}
function credits(){
  mount("Clear sources. Honest boundaries.",`<p class="dialog-note">An original concept for the Lentera Cinema brief. Layout, identity, copy, and animation were made for this demo, not copied from the reference site. Stock photographs are not studio client projects.</p><ul class="credits">${projects.filter(p=>p.source).map(p=>`<li>${p.title}: <a href="${p.source}" target="_blank" rel="noopener noreferrer">Unsplash source photograph</a>.</li>`).join("")}<li>Photographs are used as sample material under the <a href="https://unsplash.com/license" target="_blank" rel="noopener noreferrer">Unsplash license</a>. Photographers retain their rights; reuse or commercial use requires a separate permissions review, including people, property, and brands.</li><li>Inter and Lucide include local licenses. The original six-second typography animation has no audio or client footage; no copyrighted music is used.</li><li>Prices, package scope, quotes, and project context are illustrative. No operating studio, client portfolio, address, number, availability, or experience is verified.</li><li>Forms use tab memory only. There are no cookies, browser storage, analytics, accounts, backend, uploads, or payments. Data leaves only when you choose the WhatsApp link.</li><li>This edition is static HTML/CSS/JavaScript; Next.js/Tailwind and production services are not implemented. The project-specific design.md mentioned in the brief was not supplied; the design follows the shared DESIGN.md.</li></ul>`);
}
$("#service-list").innerHTML=categories.map(c=>`<a class="service-link" href="#work" data-category="${c.id}">${icon(c.icon)}<h3>${c.name}</h3><p>${c.short}</p></a>`).join("");
document.addEventListener("click",async e=>{
  const category=e.target.closest("[data-category]");if(category){e.preventDefault();filter=category.dataset.category;renderGallery();syncUrl(true,"work");$("#work").scrollIntoView();return;}
  const project=e.target.closest("[data-project]");if(project){openProject(project.dataset.project);return;}
  const filtered=e.target.closest("[data-filter]");if(filtered){filter=filtered.dataset.filter;renderGallery();syncUrl();document.querySelector(`[data-filter="${filter}"]`).focus({preventScroll:true});return;}
  const tab=e.target.closest("[data-package-tab]");if(tab){packageCategory=tab.dataset.packageTab;renderPackages();syncUrl();$(`#package-tab-${packageCategory}`).focus({preventScroll:true});return;}
  const b=e.target.closest("[data-action]");if(!b)return;const {action}=b.dataset;
  if(action==="inquire")inquiry(b.dataset.package);
  else if(action==="film")openProject("cahaya");
  else if(action==="credits")credits();
  else if(action==="close")close();
  else if(action==="previous"||action==="next"){lightIndex=(lightIndex+(action==="next"?1:-1)+lightbox.length)%lightbox.length;showProject();}
  else if(action==="download"&&draft){const url=URL.createObjectURL(new Blob([draft+"\n"],{type:"text/plain;charset=utf-8"})),a=document.createElement("a");a.href=url;a.download="lentera-unsent-message.txt";a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
  else if(action==="copy"){const field=$("#draft");if(!field)return;try{await navigator.clipboard.writeText(field.value);if(field.isConnected)toast("Draft copied. Nothing has been sent.");}catch{if(field.isConnected){field.focus();field.select();toast("Select the text and copy it using your browser shortcut.");}}}
});
$("#package-tabs").addEventListener("keydown",e=>{if(!["ArrowLeft","ArrowRight","Home","End"].includes(e.key))return;e.preventDefault();const index=categories.findIndex(c=>c.id===packageCategory),next=e.key==="Home"?0:e.key==="End"?categories.length-1:(index+(e.key==="ArrowRight"?1:-1)+categories.length)%categories.length;packageCategory=categories[next].id;renderPackages();syncUrl();$(`#package-tab-${packageCategory}`).focus({preventScroll:true});});
dialog.addEventListener("keydown",e=>{if(!$(".lightbox-nav")||!["ArrowLeft","ArrowRight"].includes(e.key)||document.activeElement?.tagName==="VIDEO")return;e.preventDefault();lightIndex=(lightIndex+(e.key==="ArrowRight"?1:-1)+lightbox.length)%lightbox.length;showProject();});
$("#close").addEventListener("click",close);dialog.addEventListener("cancel",e=>{e.preventDefault();close();});
$("#menu").addEventListener("click",()=>{const open=!$("#navigation").classList.contains("open");$("#navigation").classList.toggle("open",open);$("#menu").setAttribute("aria-expanded",String(open));});
$("#navigation").addEventListener("click",e=>{if(e.target.closest("a")){$("#navigation").classList.remove("open");$("#menu").setAttribute("aria-expanded","false");}});
document.addEventListener("keydown",e=>{if(e.key==="Escape"&&$("#navigation").classList.contains("open")){$("#menu").click();$("#menu").focus();}});
window.addEventListener("popstate",()=>{restore();renderGallery();renderPackages();});
restore();renderGallery();renderPackages();
